/**
 * Pure SVG sparkline generator.
 *
 * sparkline(values, {width, height, strokeWidth}) -> string
 *
 * - Returns an <svg> with a viewBox sized width x height.
 * - Draws a <polyline> (never a <path>) whose points map the value range
 *   onto the pixel box with 1px padding on every side.
 * - Marks the final value with a <circle>.
 * - Exposes role="img" and an aria-label summarizing first, last, min, max.
 *
 * Degenerate inputs:
 * - fewer than 2 values -> an svg containing only <title>No data</title>
 * - all-equal values    -> a horizontal line at the vertical midpoint
 */

const PAD = 1;

function formatNumber(n) {
  // Trim floating point noise but keep enough precision for tests.
  const rounded = Number(n.toFixed(3));
  return String(rounded);
}

export function sparkline(values, { width = 100, height = 24, strokeWidth = 2 } = {}) {
  if (!Array.isArray(values) || values.length < 2) {
    return (
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${formatNumber(width)} ${formatNumber(height)}" ` +
      'role="img"><title>No data</title></svg>'
    );
  }

  const innerWidth = width - PAD * 2;
  const innerHeight = height - PAD * 2;

  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = max - min;

  const stepX = innerWidth / (values.length - 1);

  const points = values.map((value, i) => {
    const x = PAD + i * stepX;
    let y;
    if (span === 0) {
      y = height / 2; // all-equal values: horizontal midline
    } else {
      y = PAD + (1 - (value - min) / span) * innerHeight;
    }
    return `${formatNumber(x)},${formatNumber(y)}`;
  });

  const [firstX, firstY] = points[0].split(',');
  const [lastX, lastY] = points[points.length - 1].split(',');

  const label =
    `Sparkline of ${values.length} values: first ${values[0]}, ` +
    `last ${values[values.length - 1]}, min ${min}, max ${max}`;

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${formatNumber(width)} ${formatNumber(height)}" ` +
    `role="img" aria-label="${label}">` +
    `<polyline fill="none" stroke="currentColor" stroke-width="${strokeWidth}" ` +
    `stroke-linecap="round" stroke-linejoin="round" points="${points.join(' ')}"/>` +
    `<circle cx="${lastX}" cy="${lastY}" r="${Math.max(strokeWidth / 2, 1)}" fill="currentColor"/>` +
    '</svg>'
  );
}

export default sparkline;

