import { describe, it, expect } from 'vitest';
import { XMLParser } from 'fast-xml-parser';
import { sparkline } from '../src/sparkline.js';

const parse = (svg) => new XMLParser({ ignoreAttributes: false }).parse(svg);

describe('sparkline', () => {
  it('produces well-formed XML with a viewBox', () => {
    const svg = sparkline([1, 2, 3]);
    expect(() => parse(svg)).not.toThrow();
    const doc = parse(svg);
    expect(doc.svg.viewBox['#text'] ?? doc.svg['@_viewBox']).toBeUndefined();
    expect(doc.svg['@_viewBox']).toBe('0 0 100 24');
  });

  it('uses a polyline (not a path) with one point per value', () => {
    const values = [3, 7, 1, 9, 4];
    const doc = parse(sparkline(values));
    expect(doc.svg.polyline).toBeDefined();
    expect(doc.svg.path).toBeUndefined();
    const points = doc.svg.polyline['@_points'].trim().split(/\s+/);
    expect(points).toHaveLength(values.length);
  });

  it('hits the padded edges at the first and last x coordinates', () => {
    const width = 120;
    const values = [5, 1, 8, 3];
    const doc = parse(sparkline(values, { width }));
    const points = doc.svg.polyline['@_points'].trim().split(/\s+/).map((p) =>
      p.split(',').map(Number),
    );
    expect(points[0][0]).toBeCloseTo(1); // left padding edge
    expect(points[points.length - 1][0]).toBeCloseTo(width - 1); // right padding edge
    // intermediate points are evenly spaced between the edges
    const step = (width - 2) / (values.length - 1);
    points.forEach(([x], i) => expect(x).toBeCloseTo(1 + i * step));
  });

  it('maps extremes to the padded top and bottom edges', () => {
    const height = 30;
    const values = [10, 0, 5];
    const doc = parse(sparkline(values, { height }));
    const points = doc.svg.polyline['@_points'].trim().split(/\s+/).map((p) =>
      Number(p.split(',')[1]),
    );
    expect(points[0]).toBeCloseTo(1); // max value -> top padding
    expect(points[1]).toBeCloseTo(height - 1); // min value -> bottom padding
  });

  it('draws a horizontal midline for all-equal values', () => {
    const height = 40;
    const doc = parse(sparkline([7, 7, 7, 7], { height }));
    const points = doc.svg.polyline['@_points'].trim().split(/\s+/).map((p) =>
      Number(p.split(',')[1]),
    );
    expect(points.every((y) => y === height / 2)).toBe(true);
  });

  it('marks the final point with a circle at its coordinates', () => {
    const doc = parse(sparkline([1, 2, 3]));
    const circle = doc.svg.circle;
    expect(circle).toBeDefined();
    const points = doc.svg.polyline['@_points'].trim().split(/\s+/);
    const [lastX, lastY] = points[points.length - 1].split(',').map(Number);
    expect(Number(circle['@_cx'])).toBeCloseTo(lastX);
    expect(Number(circle['@_cy'])).toBeCloseTo(lastY);
  });

  it('returns a No data title-only svg for fewer than 2 values', () => {
    for (const input of [[], [42]]) {
      const doc = parse(sparkline(input));
      expect(doc.svg.title).toBe('No data');
      expect(doc.svg.polyline).toBeUndefined();
      expect(doc.svg.circle).toBeUndefined();
      expect(Object.keys(doc.svg)).toHaveLength(3); // xmlns, viewBox, title only... plus attrs
    }
  });

  it('summarizes first, last, min and max in the aria-label', () => {
    const values = [4, -2, 9, 0];
    const doc = parse(sparkline(values));
    const label = doc.svg['@_aria-label'];
    expect(label).toContain('first 4');
    expect(label).toContain('last 0');
    expect(label).toContain('min -2');
    expect(label).toContain('max 9');
    expect(doc.svg['@_role']).toBe('img');
  });
});

